using System.Text.Json.Serialization;

namespace Explore.Blazor.Models;

// Operations are generated by the BFF. A browser cannot adopt an existing operation.
[JsonUnmappedMemberHandling(JsonUnmappedMemberHandling.Disallow)]
public sealed record LocalVisitorEnrollmentStartRequest(string? ReturnUrl = null)
{
    public override string ToString() => nameof(LocalVisitorEnrollmentStartRequest);
}

[JsonUnmappedMemberHandling(JsonUnmappedMemberHandling.Disallow)]
public sealed record LocalVisitorEnrollmentRegisterRequest(string Username, string Password, string? Email = null)
{
    public override string ToString() => nameof(LocalVisitorEnrollmentRegisterRequest);
}

public sealed record LocalVisitorEnrollmentStatus(string Status, string? RedirectUrl = null)
{
    public override string ToString() => nameof(LocalVisitorEnrollmentStatus);
}
